nodes.func:
msg.payload = { status: 'success', job: 'maintain_weather_device_retention', completed_at: new Date().toISOString() };
node.status({fill:'green',shape:'dot',text:'weather + device retention succeeded'});
return msg;

const rows = Array.isArray(msg.payload) ? msg.payload : [];
const row = rows[0] || {};
const age = Number(row.FullSuccessAgeHours);
const pruningEnabled = Number(row.PruningEnabled) === 1 || row.PruningEnabled === true;
const ready = Number(row.ReadyToPrune) === 1 || row.ReadyToPrune === true;
const stale = !row.LastFullSuccessUTC || !Number.isFinite(age) || age > 36;
const unhealthy = !pruningEnabled || !ready || stale;

if (!unhealthy) {
    node.status({fill:'green',shape:'dot',text:`complete success ${age}h ago`});
    msg.payload = {
        status: 'healthy',
        full_success_age_hours: age,
        last_full_success_utc: row.LastFullSuccessUTC,
        last_archive_utc: row.LastArchiveSuccessUTC,
        last_validation_utc: row.LastValidationUTC,
        last_weather_prune_utc: row.LastWeatherPruneSuccessUTC,
        last_device_prune_utc: row.LastDevicePruneSuccessUTC
    };
    return [null, msg];
}

node.status({fill:'red',shape:'ring',text:'weather retention unhealthy'});
const now = Date.now();
const lastAlert = flow.get('weatherDeviceRetentionLastStaleAlert') || 0;
if (now - lastAlert < 12 * 60 * 60 * 1000) return [null, null];
flow.set('weatherDeviceRetentionLastStaleAlert', now);
msg.title = 'Weather/device retention is unhealthy';
msg.payload = `Weather/device retention health failed. Ready: ${ready}. Pruning enabled: ${pruningEnabled}. Last complete success UTC: ${row.LastFullSuccessUTC || 'never'} (age ${Number.isFinite(age) ? age : 'unknown'}h). Last note: ${row.LastNote || 'none'}.`;
msg.device = global.get('BradPhoneNM') || 'pixel8';
return [msg, null];

const detail = (msg.error && msg.error.message) ? msg.error.message : String(msg.payload || 'unknown database error');
const now = Date.now();
const lastAlert = flow.get('weatherDeviceRetentionLastErrorAlert') || 0;
if (now - lastAlert < 30 * 60 * 1000) return null;
flow.set('weatherDeviceRetentionLastErrorAlert', now);
msg.title = 'Weather/device retention failure';
msg.payload = `Weather archive/prune or DeviceMonitoring prune failed: ${detail}. Guarded deletion stops on archive validation failure.`;
msg.device = global.get('BradPhoneNM') || 'pixel8';
return msg;
